<?php
require_once __DIR__ . '/../app/layout.php';$u=require_role(['ngo','admin']);$pdo=db();$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();try{$action=$_POST['action']??'';
  if($action==='create'){$name=trim($_POST['display_name']??'');$size=(int)($_POST['household_size']??1);$area=trim($_POST['area']??'');$phone=trim($_POST['contact_phone']??'');$notes=trim($_POST['notes']??'');if($name===''||$area===''||$size<1||$size>100)throw new RuntimeException('Enter a display name, area and household size between 1 and 100.');if($phone!==''&&!bangladesh_phone_valid($phone))throw new RuntimeException('Enter a valid Bangladesh mobile number or leave the phone field blank.');$owner=$u['role']==='admin'?(int)($_POST['ngo_id']??0):(int)$u['id'];$q=$pdo->prepare("SELECT id FROM users WHERE id=? AND role='ngo' AND is_active=1" );$q->execute([$owner]);if(!$q->fetch())throw new RuntimeException('Choose a valid active NGO.');$pdo->prepare('INSERT INTO beneficiaries(ngo_id,display_name,household_size,area,contact_phone,notes) VALUES(?,?,?,?,?,?)')->execute([$owner,$name,$size,$area,$phone?:null,$notes?:null]);$id=(int)$pdo->lastInsertId();audit((int)$u['id'],'beneficiary_created','beneficiaries',$id,'NGO='.$owner);flash('Beneficiary profile created. Personal data is restricted to authorized accounts.');redirect('beneficiaries.php');}
  elseif($action==='need'){$bid=(int)($_POST['beneficiary_id']??0);$cat=trim($_POST['food_category']??'');$qty=(float)($_POST['required_quantity']??0);$unit=$_POST['unit']??'kg';$priority=$_POST['priority_level']??'normal';if($cat===''||$qty<=0||!in_array($unit,['kg','portion','meal','box'],true)||!in_array($priority,['low','normal','high','urgent'],true))throw new RuntimeException('Enter a category, positive quantity, valid unit and priority.');$q=$pdo->prepare('SELECT id FROM beneficiaries WHERE id=?'.($u['role']==='admin'?'':' AND ngo_id=?'));$q->execute($u['role']==='admin'?[$bid]:[$bid,$u['id']]);if(!$q->fetch())throw new RuntimeException('Beneficiary not found or access denied.');$pdo->prepare('INSERT INTO beneficiary_needs(beneficiary_id,food_category,required_quantity,unit,priority_level) VALUES(?,?,?,?,?)')->execute([$bid,$cat,$qty,$unit,$priority]);flash('Beneficiary need recorded.');redirect('beneficiaries.php?view='.$bid);}
  elseif($action==='status'){$bid=(int)($_POST['beneficiary_id']??0);$status=$_POST['status']??'';if(!in_array($status,['active','inactive'],true))throw new RuntimeException('Invalid status.');$q=$pdo->prepare('SELECT id FROM beneficiaries WHERE id=?'.($u['role']==='admin'?'':' AND ngo_id=?'));$q->execute($u['role']==='admin'?[$bid]:[$bid,$u['id']]);if(!$q->fetch())throw new RuntimeException('Beneficiary not found or access denied.');$pdo->prepare('UPDATE beneficiaries SET status=? WHERE id=?')->execute([$status,$bid]);audit((int)$u['id'],'beneficiary_status_changed','beneficiaries',$bid,$status);flash('Beneficiary status updated.');redirect('beneficiaries.php');}
  elseif($action==='link_distribution'){$bid=(int)($_POST['beneficiary_id']??0);$did=(int)($_POST['distribution_id']??0);$meals=(int)($_POST['meals_allocated']??0);$notes=trim($_POST['link_notes']??'');if($meals<0)throw new RuntimeException('Meals allocated cannot be negative.');$pdo->beginTransaction();$q=$pdo->prepare('SELECT id FROM beneficiaries WHERE id=?'.($u['role']==='admin'?'':' AND ngo_id=?').' FOR UPDATE');$q->execute($u['role']==='admin'?[$bid]:[$bid,$u['id']]);if(!$q->fetch())throw new RuntimeException('Beneficiary not found or access denied.');$q=$pdo->prepare('SELECT d.* FROM distributions d JOIN donation_requests dr ON dr.id=d.donation_request_id WHERE d.id=?'.($u['role']==='admin'?'':' AND dr.requested_by=?').' FOR UPDATE');$q->execute($u['role']==='admin'?[$did]:[$did,$u['id']]);$dist=$q->fetch();if(!$dist)throw new RuntimeException('Distribution record not found or does not belong to your NGO.');$q=$pdo->prepare('SELECT COALESCE(SUM(meals_allocated),0) FROM beneficiary_distribution_links WHERE distribution_id=?');$q->execute([$did]);$used=(int)$q->fetchColumn();if($used+$meals>(int)$dist['meals_distributed'])throw new RuntimeException('Allocated meals exceed the distribution record total.');$pdo->prepare('INSERT INTO beneficiary_distribution_links(beneficiary_id,distribution_id,meals_allocated,notes) VALUES(?,?,?,?)')->execute([$bid,$did,$meals,$notes?:null]);$pdo->commit();flash('Distribution linked to beneficiary history.');redirect('beneficiaries.php?view='.$bid);}
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$errors[]=$e instanceof RuntimeException?$e->getMessage():'Action failed. Check migration, access and duplicate links.';}}
if($u['role']==='admin'){$rows=$pdo->query('SELECT b.*,u.name AS ngo_name FROM beneficiaries b JOIN users u ON u.id=b.ngo_id ORDER BY b.updated_at DESC')->fetchAll();$ngos=$pdo->query("SELECT id,name FROM users WHERE role='ngo' AND is_active=1 ORDER BY name")->fetchAll();}else{$q=$pdo->prepare('SELECT b.*,u.name AS ngo_name FROM beneficiaries b JOIN users u ON u.id=b.ngo_id WHERE b.ngo_id=? ORDER BY b.updated_at DESC');$q->execute([$u['id']]);$rows=$q->fetchAll();$ngos=[];}
$viewId=(int)($_GET['view']??0);$view=null;$needs=[];$links=[];if($viewId){$q=$pdo->prepare('SELECT b.*,u.name AS ngo_name FROM beneficiaries b JOIN users u ON u.id=b.ngo_id WHERE b.id=?'.($u['role']==='admin'?'':' AND b.ngo_id=?'));$q->execute($u['role']==='admin'?[$viewId]:[$viewId,$u['id']]);$view=$q->fetch();if($view){$q=$pdo->prepare('SELECT * FROM beneficiary_needs WHERE beneficiary_id=? ORDER BY assessed_at DESC');$q->execute([$viewId]);$needs=$q->fetchAll();$q=$pdo->prepare('SELECT l.*,d.meals_distributed,d.created_at AS distribution_date,dr.id AS request_id,sf.food_name FROM beneficiary_distribution_links l JOIN distributions d ON d.id=l.distribution_id JOIN donation_requests dr ON dr.id=d.donation_request_id JOIN surplus_food sf ON sf.id=dr.surplus_food_id WHERE l.beneficiary_id=? ORDER BY l.created_at DESC');$q->execute([$viewId]);$links=$q->fetchAll();}}
if($u['role']==='admin')$distRows=$pdo->query('SELECT d.id,d.meals_distributed,sf.food_name,ngo.name AS ngo_name FROM distributions d JOIN donation_requests dr ON dr.id=d.donation_request_id JOIN surplus_food sf ON sf.id=dr.surplus_food_id JOIN users ngo ON ngo.id=d.recorded_by ORDER BY d.created_at DESC LIMIT 100')->fetchAll();else{$q=$pdo->prepare('SELECT d.id,d.meals_distributed,sf.food_name FROM distributions d JOIN donation_requests dr ON dr.id=d.donation_request_id JOIN surplus_food sf ON sf.id=dr.surplus_food_id WHERE dr.requested_by=? ORDER BY d.created_at DESC');$q->execute([$u['id']]);$distRows=$q->fetchAll();}
page_header('Beneficiary management');?>
<div class="page-intro"><div class="eyebrow">NEEDS & DISTRIBUTION</div><h1>Beneficiary <em>management.</em></h1><p>Maintain household-level needs and link recorded distributions to assistance history. Keep personal information to the minimum necessary.</p></div><?php foreach($errors as $err):?><div class="alert error"><?=e($err)?></div><?php endforeach;?>
<div class="form-panel"><h2>Add beneficiary / household</h2><form method="post" class="form-grid"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="create"><?php if($u['role']==='admin'):?><label class="full">NGO owner<select name="ngo_id" required><option value="">Select NGO</option><?php foreach($ngos as $n):?><option value="<?=(int)$n['id']?>"><?=e($n['name'])?></option><?php endforeach;?></select></label><?php endif;?><label>Display name / reference<input name="display_name" maxlength="150" required placeholder="Household A-001"></label><label>Household size<input type="number" name="household_size" min="1" max="100" value="1" required></label><label>Area / community<input name="area" maxlength="180" required></label><label>Contact phone (optional)<input name="contact_phone" maxlength="20" placeholder="01XXXXXXXXX"></label><label class="full">Notes (avoid sensitive details)<textarea name="notes" maxlength="3000" rows="2"></textarea></label><div class="full"><button class="btn" type="submit">Save beneficiary</button></div></form></div>
<div class="section-heading"><div><div class="eyebrow">AUTHORIZED RECORDS</div><h2>Beneficiaries</h2></div></div><div class="table-wrap"><table><thead><tr><th>Reference</th><th>NGO</th><th>Household</th><th>Area</th><th>Status</th><th>Phone</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['display_name'])?></td><td><?=e($r['ngo_name'])?></td><td><?=(int)$r['household_size']?> people</td><td><?=e($r['area'])?></td><td><?=e($r['status'])?></td><td><?=e($r['contact_phone']??'')?></td><td><div class="inline-actions"><a href="<?=e(url('beneficiaries.php?view='.(int)$r['id']))?>">Details</a><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="status"><input type="hidden" name="beneficiary_id" value="<?=(int)$r['id']?>"><input type="hidden" name="status" value="<?=$r['status']==='active'?'inactive':'active'?>"><button class="btn btn-outline btn-sm" type="submit"><?=$r['status']==='active'?'Deactivate':'Activate'?></button></form></div></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="7" class="table-empty">No beneficiary records yet.</td></tr><?php endif;?></tbody></table></div>
<?php if($view):?><div class="section-heading"><div><div class="eyebrow">BENEFICIARY DETAIL</div><h2><?=e($view['display_name'])?> · <?=e($view['area'])?></h2><p class="muted">Owned by <?=e($view['ngo_name'])?>. This information is not shown on public pages.</p></div></div><div class="form-panel"><h3>Add assessed need</h3><form method="post" class="form-grid"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="need"><input type="hidden" name="beneficiary_id" value="<?=$viewId?>"><label>Food category<input name="food_category" maxlength="100" required></label><label>Quantity needed<input type="number" min="0.01" step="0.01" name="required_quantity" required></label><label>Unit<select name="unit"><option>kg</option><option>portion</option><option>meal</option><option>box</option></select></label><label>Priority<select name="priority_level"><option>normal</option><option>low</option><option>high</option><option>urgent</option></select></label><div class="full"><button class="btn" type="submit">Record need</button></div></form></div><div class="section-heading"><div><h2>Assessed needs</h2></div></div><div class="table-wrap"><table><thead><tr><th>Category</th><th>Quantity</th><th>Priority</th><th>Status</th><th>Assessed</th></tr></thead><tbody><?php foreach($needs as $n):?><tr><td><?=e($n['food_category'])?></td><td><?=e($n['required_quantity'])?> <?=e($n['unit'])?></td><td><?=e($n['priority_level'])?></td><td><?=e($n['status'])?></td><td><?=e($n['assessed_at'])?></td></tr><?php endforeach;?><?php if(!$needs):?><tr><td colspan="5" class="table-empty">No needs recorded.</td></tr><?php endif;?></tbody></table></div><div class="form-panel"><h3>Link an existing distribution</h3><form method="post" class="form-grid"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="link_distribution"><input type="hidden" name="beneficiary_id" value="<?=$viewId?>"><label class="full">Distribution record<select name="distribution_id" required><option value="">Select distribution</option><?php foreach($distRows as $d):?><option value="<?=(int)$d['id']?>">#<?=(int)$d['id']?> · <?=e($d['food_name'])?> · <?=e($d['meals_distributed'])?> meals</option><?php endforeach;?></select></label><label>Meals allocated<input type="number" min="0" name="meals_allocated" value="0" required></label><label>Notes<input name="link_notes" maxlength="500"></label><div class="full"><button class="btn" type="submit">Link distribution</button></div></form></div><div class="section-heading"><div><h2>Distribution history</h2></div></div><div class="table-wrap"><table><thead><tr><th>Date</th><th>Food</th><th>Request</th><th>Meals allocated</th><th>Notes</th></tr></thead><tbody><?php foreach($links as $l):?><tr><td><?=e($l['distribution_date'])?></td><td><?=e($l['food_name'])?></td><td>#<?=(int)$l['request_id']?></td><td><?=(int)$l['meals_allocated']?></td><td><?=e($l['notes']??'')?></td></tr><?php endforeach;?><?php if(!$links):?><tr><td colspan="5" class="table-empty">No distribution linked to this beneficiary yet.</td></tr><?php endif;?></tbody></table></div><?php elseif($viewId):?><div class="alert error">Beneficiary not found or access denied.</div><?php endif;?>
